	public function action($id,$action){if($this->input->method(TRUE)!=='POST')show_error('Method Not Allowed',405);$plan=$this->plan_or_404($id);$map=array('submit'=>array('elemental_costs.manage','DRAFT','FOR_REVIEW'),'return-draft'=>array('elemental_costs.approve','FOR_REVIEW','DRAFT'),'approve'=>array('elemental_costs.approve','FOR_REVIEW','APPROVED'),'publish'=>array('elemental_costs.approve','APPROVED','PUBLISHED'),'archive'=>array('elemental_costs.approve','PUBLISHED','ARCHIVED'));if(!isset($map[$action]))show_404();$rule=$map[$action];$this->authorize($rule[0]);if($plan->plan_status!==$rule[1])show_error('This action is not valid for the current plan status.',409,'Invalid Transition');if(!$this->Elemental_cost_model->transition($id,$rule[1],$rule[2],$this->current_user->user_id))show_error('Unable to update the elemental plan status.',500);log_message('info','Elemental plan transition: id='.(int)$id.' action='.$action.' actor='.(int)$this->current_user->user_id);$this->session->set_flashdata('elemental_success','Elemental plan status changed to '.str_replace('_',' ',$rule[2]).'.');redirect('elemental-costs/'.$id);}

